import React, { useState } from 'react';
import { Calculator, Info } from "lucide-react";

// Твои импорты
import MethodSelector from "../components/lab3/MethodSelector";
import { Header } from "../components/layout/Header";
import { Tabs } from "../components/layout/Tabs";
import FunctionSelector from "../components/lab3/FunctionSelector";
import IntegrationForm from "../components/lab3/IntegrationForm";
import IntegrationChart from "../components/lab3/IntegrationChart";
import ResultsTable from "../components/lab3/ResultsTable";

// Импорт API и типов
import { lab3Api } from '../services/api';
import { IntegrationRequest, IntegrationResponse } from '../types';

const IntegrationPage: React.FC = () => {
    // Состояние табов
    const [activeTab, setActiveTab] = useState<'equation' | 'system'>('equation'); // Оставил твои ключи из Tabs

    // Состояние запроса
    const [request, setRequest] = useState<IntegrationRequest>({
        functionId: 1,
        methodId: 5, // Симпсон по умолчанию
        a: 0,
        b: 2,
        epsilon: 0.001
    });

    // Состояние ответа
    const [response, setResponse] = useState<IntegrationResponse | null>(null);
    const [loading, setLoading] = useState(false);

    const handleCalculate = async () => {
        setLoading(true);
        try {
            const res = await lab3Api.calculate(request);
            setResponse(res.data);
        } catch (err: any) {
            alert(err.response?.data?.message || "Ошибка при связи с сервером");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 pb-12">
            <Header />

            <main className="container mx-auto px-4 max-w-6xl">
                {/* Твой компонент Tabs (используем его как переключатель Калькулятор/Инфо) */}

                {activeTab === 'equation' ? (
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-500">

                        {/* ЛЕВАЯ КОЛОНКА: Ввод данных */}
                        <div className="lg:col-span-5 space-y-6">
                            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                                <div className="flex items-center gap-2 mb-6">
                                    <Calculator className="text-indigo-600" size={20} />
                                    <h2 className="text-lg font-bold text-slate-800">Конфигурация</h2>
                                </div>

                                <div className="space-y-6">
                                    <FunctionSelector
                                        selected={request.functionId}
                                        onChange={(id) => setRequest({...request, functionId: id})}
                                    />

                                    <MethodSelector
                                        selected={request.methodId}
                                        onChange={(id) => setRequest({...request, methodId: id})}
                                    />

                                    <IntegrationForm
                                        request={request}
                                        setRequest={setRequest}
                                        onCalculate={handleCalculate}
                                        loading={loading}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ПРАВАЯ КОЛОНКА: График и Таблица */}
                        <div className="lg:col-span-7 space-y-6">
                            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 min-h-[500px] flex flex-col">
                                {response ? (
                                    <div className="animate-in zoom-in-95 duration-300">
                                        <h2 className="text-lg font-bold mb-4 text-slate-800">Результат визуализации</h2>
                                        <IntegrationChart
                                            points={response.graphPoints}
                                            a={request.a}
                                            b={request.b}
                                        />
                                        <ResultsTable response={response} />
                                    </div>
                                ) : (
                                    <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
                                        <div className="bg-slate-50 p-6 rounded-full mb-4">
                                            <Calculator size={40} className="opacity-20" />
                                        </div>
                                        <p className="text-center max-w-[250px]">
                                            Настройте параметры слева и нажмите кнопку расчета
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>

                    </div>
                ) : (
                    /* ТАБ С ИНФОРМАЦИЕЙ */
                    <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 animate-in slide-in-from-bottom-4 duration-500">
                        <div className="flex items-center gap-3 mb-6">
                            <Info className="text-indigo-600" size={24} />
                            <h2 className="text-2xl font-bold text-slate-800">Справка по ЛР №3</h2>
                        </div>
                        <article className="prose prose-slate max-w-none">
                            <p className="text-slate-600 mb-4">
                                Лабораторная работа посвящена численному интегрированию функций методами:
                            </p>
                            <ul className="list-disc pl-6 text-slate-600 space-y-2">
                                <li><b>Методы прямоугольников:</b> Левые, Правые, Средние (порядок точности $O(h^2)$ для средних).</li>
                                <li><b>Метод трапеций:</b> Аппроксимация подынтегральной функции ломаной линией.</li>
                                <li><b>Метод Симпсона:</b> Использование параболической интерполяции (наивысшая точность $O(h^4)$).</li>
                            </ul>
                            <div className="mt-6 p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                                <p className="text-indigo-900 text-sm">
                                    <b>Правило Рунге:</b> Для оценки погрешности используется сравнение результатов на сетках с шагом $h$ и $h/2$.
                                </p>
                            </div>
                        </article>
                    </div>
                )}
            </main>
        </div>
    );
};

export default IntegrationPage;
